FROM sales |> WHERE NOT (region = 'west' AND t >= TIMESTAMP '2024-03-01' AND t < TIMESTAMP '2024-05-01') |> WHERE region <> 'north' |> AGGREGATE sum(units) AS sum_units GROUP BY region |> CALL impute(region, [], sum_units, value => 0, keys => ['east', 'west', 'north'], flag => imputed) |> AGGREGATE bar(x => scaled(region, scale => scale(domain => ['east', 'west', 'north'])), y => scaled(sum_units, title => 'sum(units)'), orient => 'vertical') AS bar
